ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
    status: 500,
    message: error.description default "Failed to retrieve opportunities",
    correlationId: correlationId,
    timestamp: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ"}
}

%dw 2.0
output application/json
---
{
    status: 404,
    message: "Opportunity not found: " ++ attributes.uriParams.oppId,
    correlationId: correlationId,
    timestamp: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ"}
}

%dw 2.0
output application/json
---
{
    status: 500,
    message: error.description default "Failed to update opportunity",
    correlationId: correlationId,
    timestamp: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ"}
}

%dw 2.0
output application/json
---
{
    status: 400,
    message: vars.validationMessage,
    correlationId: correlationId,
    timestamp: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ"}
}

%dw 2.0
output application/json
---
{
    status: 404,
    message: "Opportunity not found: " ++ attributes.uriParams.oppId,
    correlationId: correlationId,
    timestamp: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ"}
}

%dw 2.0
output application/json
---
{
    status: 500,
    message: error.description default "Failed to close opportunity",
    correlationId: correlationId,
    timestamp: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ"}
}
